namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public required string Code { get; set; }
    public required string Title { get; set; }
    public required string Description { get; set; }
    public int Credits { get; set; }
    public required string Schedule { get; set; }
    public required string Room { get; set; }
    public int DepartmentId { get; set; }
    public required Department Department { get; set; }
    public required Instructor Instructor { get; set; }
    public bool IsFeatured { get; set; }
}

namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public required string Name { get; set; }
    public required string Abbreviation { get; set; }
    public required string Description { get; set; }
}

namespace UniversityCourseCatalog.Models;

public class Instructor
{
    public int Id { get; set; }
    public required string Name { get; set; }
    public required string Title { get; set; }
    public required string Bio { get; set; }
    public required string Email { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Full name is required.")]
    [StringLength(100)]
    public string Name { get; set; } = "";

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Za-z0-9]{6,12}$", ErrorMessage = "Student ID must be 6–12 alphanumeric characters.")]
    public string StudentId { get; set; } = "";

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Instructor> _instructors;
    private readonly List<Course> _courses;
    private readonly List<EnrollmentRequest> _enrollments = [];

    public CatalogService()
    {
        _departments =
        [
            new Department { Id = 1, Name = "Computer Science", Abbreviation = "CS", Description = "Study of computation, algorithms, and information systems." },
            new Department { Id = 2, Name = "Mathematics", Abbreviation = "MATH", Description = "Pure and applied mathematics, including statistics and analysis." },
            new Department { Id = 3, Name = "Physics", Abbreviation = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new Department { Id = 4, Name = "English", Abbreviation = "ENG", Description = "Literature, writing, and language studies." },
            new Department { Id = 5, Name = "History", Abbreviation = "HIST", Description = "Study of past events, societies, and civilizations." },
        ];

        _instructors =
        [
            new Instructor { Id = 1, Name = "Dr. Alice Chen", Title = "Professor", Bio = "Dr. Chen specializes in artificial intelligence and machine learning. She has published over 50 papers in top-tier conferences and holds three patents in natural language processing.", Email = "achen@university.edu" },
            new Instructor { Id = 2, Name = "Dr. Robert Kim", Title = "Associate Professor", Bio = "Dr. Kim's research focuses on distributed systems and cloud computing. He previously worked at a major tech company before joining academia.", Email = "rkim@university.edu" },
            new Instructor { Id = 3, Name = "Dr. Maria Lopez", Title = "Professor", Bio = "Dr. Lopez is an expert in abstract algebra and number theory. She is the author of two widely adopted textbooks on modern algebra.", Email = "mlopez@university.edu" },
            new Instructor { Id = 4, Name = "Dr. James Wright", Title = "Assistant Professor", Bio = "Dr. Wright researches quantum mechanics and condensed matter physics. He completed his postdoctoral work at CERN.", Email = "jwright@university.edu" },
            new Instructor { Id = 5, Name = "Prof. Sarah Davis", Title = "Professor", Bio = "Prof. Davis is a published novelist and literary critic specializing in 20th-century American fiction. She has won multiple teaching awards.", Email = "sdavis@university.edu" },
            new Instructor { Id = 6, Name = "Dr. Michael Patel", Title = "Associate Professor", Bio = "Dr. Patel is a historian of modern Europe with a focus on the World Wars. He has authored three books and curated museum exhibits.", Email = "mpatel@university.edu" },
            new Instructor { Id = 7, Name = "Dr. Emily Zhao", Title = "Assistant Professor", Bio = "Dr. Zhao specializes in applied statistics and data science. She collaborates with the medical school on clinical trial design.", Email = "ezhao@university.edu" },
        ];

        _courses =
        [
            new Course { Id = 1, Code = "CS 101", Title = "Introduction to Computer Science", Description = "A foundational course covering programming fundamentals, computational thinking, and problem-solving using Python. No prior experience required.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Room = "Science Hall 201", DepartmentId = 1, Department = _departments[0], Instructor = _instructors[0], IsFeatured = true },
            new Course { Id = 2, Code = "CS 301", Title = "Data Structures and Algorithms", Description = "Study of fundamental data structures (trees, graphs, hash tables) and algorithm design techniques (divide-and-conquer, dynamic programming, greedy algorithms). Includes complexity analysis.", Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", Room = "Science Hall 305", DepartmentId = 1, Department = _departments[0], Instructor = _instructors[1] },
            new Course { Id = 3, Code = "CS 420", Title = "Machine Learning", Description = "Introduction to machine learning concepts including supervised and unsupervised learning, neural networks, and model evaluation. Hands-on projects with real datasets.", Credits = 3, Schedule = "Tue/Thu 2:00–3:20 PM", Room = "Tech Center 110", DepartmentId = 1, Department = _departments[0], Instructor = _instructors[0], IsFeatured = true },
            new Course { Id = 4, Code = "MATH 201", Title = "Linear Algebra", Description = "Vectors, matrices, linear transformations, eigenvalues, and applications to computer science and engineering.", Credits = 3, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Room = "Math Building 102", DepartmentId = 2, Department = _departments[1], Instructor = _instructors[2] },
            new Course { Id = 5, Code = "MATH 301", Title = "Abstract Algebra", Description = "Groups, rings, fields, and their applications. Emphasis on proof-writing and abstract reasoning.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", Room = "Math Building 204", DepartmentId = 2, Department = _departments[1], Instructor = _instructors[2], IsFeatured = true },
            new Course { Id = 6, Code = "MATH 210", Title = "Statistics and Probability", Description = "Probability theory, random variables, distributions, hypothesis testing, and regression analysis with practical applications.", Credits = 4, Schedule = "Mon/Wed 2:00–3:20 PM", Room = "Math Building 108", DepartmentId = 2, Department = _departments[1], Instructor = _instructors[6] },
            new Course { Id = 7, Code = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Calculus-based introduction to physics with laboratory sessions.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", Room = "Physics Lab 101", DepartmentId = 3, Department = _departments[2], Instructor = _instructors[3] },
            new Course { Id = 8, Code = "PHYS 310", Title = "Quantum Mechanics", Description = "Introduction to quantum theory: wave functions, Schrödinger equation, angular momentum, and applications to atomic and molecular systems.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", Room = "Physics Lab 203", DepartmentId = 3, Department = _departments[2], Instructor = _instructors[3], IsFeatured = true },
            new Course { Id = 9, Code = "ENG 101", Title = "College Writing", Description = "Develop clear, effective writing skills through essays, research papers, and peer review. Focus on argumentation and critical analysis.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", Room = "Humanities 110", DepartmentId = 4, Department = _departments[3], Instructor = _instructors[4] },
            new Course { Id = 10, Code = "ENG 250", Title = "American Literature", Description = "Survey of American literary works from the colonial period through the 21st century, including novels, poetry, and essays.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", Room = "Humanities 215", DepartmentId = 4, Department = _departments[3], Instructor = _instructors[4] },
            new Course { Id = 11, Code = "HIST 101", Title = "World History to 1500", Description = "Survey of world civilizations from prehistory to 1500 CE, covering cultural, political, and economic developments across regions.", Credits = 3, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Room = "Liberal Arts 302", DepartmentId = 5, Department = _departments[4], Instructor = _instructors[5] },
            new Course { Id = 12, Code = "HIST 320", Title = "Modern European History", Description = "Europe from the French Revolution to the present. Examines political revolutions, industrialization, world wars, and the European Union.", Credits = 3, Schedule = "Tue/Thu 3:30–4:50 PM", Room = "Liberal Arts 310", DepartmentId = 5, Department = _departments[4], Instructor = _instructors[5] },
        ];
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? search = null, int? departmentId = null, int? credits = null)
    {
        var query = _courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Instructor.Name.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        if (departmentId.HasValue && departmentId.Value > 0)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        if (credits.HasValue && credits.Value > 0)
        {
            query = query.Where(c => c.Credits == credits.Value);
        }

        return query.OrderBy(c => c.Code).ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public List<int> GetDistinctCredits() => _courses.Select(c => c.Credits).Distinct().OrderBy(c => c).ToList();

    public void SubmitEnrollment(EnrollmentRequest request)
    {
        _enrollments.Add(request);
    }
}

