+                    <input type="text" id="studentId" name="Model.StudentId" value="@Model.StudentId" class="form-control" placeholder="e.g. STU123456" />
+                    @if (errors.ContainsKey(nameof(Model.StudentId)))
+                    {
+                        <div class="text-danger small mt-1">@errors[nameof(Model.StudentId)]</div>
+                    }
+                </div>
+
+                <div class="mb-3">
+                    <label for="courseId" class="form-label">Course</label>
+                    <select id="courseId" name="Model.CourseId" class="form-select">
+                        <option value="0">-- Select a course --</option>
+                        @foreach (var course in allCourses)
+                        {
+                            <option value="@course.Id" selected="@(Model.CourseId == course.Id)">@course.Code – @course.Title (@course.Credits cr)</option>
+                        }
+                    </select>
+                    @if (errors.ContainsKey(nameof(Model.CourseId)))
+                    {
+                        <div class="text-danger small mt-1">@errors[nameof(Model.CourseId)]</div>
+                    }
+                </div>
+
+                <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
+                <a href="courses" class="btn btn-outline-secondary ms-2">Cancel</a>
+            </form>
+        </div>
+
+        <div class="col-lg-6 mt-4 mt-lg-0">
+            <div class="card bg-light">
+                <div class="card-body">
+                    <h5 class="card-title">How Enrollment Works</h5>
+                    <ol class="mb-0">
+                        <li>Fill out the form with your name, student ID, and desired course.</li>
+                        <li>Submit the form to send your enrollment request.</li>
+                        <li>The registrar's office will review your request and confirm via email.</li>
+                    </ol>
+                </div>
+            </div>
+        </div>
+    </div>
+}
+
+@code {
+    [SupplyParameterFromForm] public EnrollmentRequest Model { get; set; } = new();
+    [SupplyParameterFromQuery] public int? CourseId { get; set; }
+
+    private List<Course> allCourses = [];
+    private Dictionary<string, string> errors = new();
+    private bool submitted;
+
+    protected override void OnInitialized()
+    {
+        allCourses = Catalog.GetCourses();
+
+        // Pre-select course if provided via query string
+        if (CourseId.HasValue && Model.CourseId == 0)
+        {
+            Model.CourseId = CourseId.Value;
+        }
+    }
+
+    protected override void OnParametersSet()
+    {
+        // Handle form POST
+        if (HttpMethods.IsPost(HttpContext?.Request.Method ?? ""))
+        {
+            errors = Validate(Model);
+            if (errors.Count == 0)
+            {
+                Catalog.SubmitEnrollment(Model);
+                submitted = true;
+            }
+        }
+    }
+
+    [CascadingParameter] public HttpContext? HttpContext { get; set; }
+
+    private static Dictionary<string, string> Validate(EnrollmentRequest model)
+    {
+        var results = new Dictionary<string, string>();
+        var context = new System.ComponentModel.DataAnnotations.ValidationContext(model);
+        var validationResults = new List<System.ComponentModel.DataAnnotations.ValidationResult>();
+
+        if (!System.ComponentModel.DataAnnotations.Validator.TryValidateObject(model, context, validationResults, true))
+        {
+            foreach (var vr in validationResults)
+            {
+                foreach (var member in vr.MemberNames)
+                {
+                    if (!results.ContainsKey(member))
+                    {
+                        results[member] = vr.ErrorMessage ?? "Invalid value.";
+                    }
+                }
+            }
+        }
+
+        return results;
+    }
+}
